select COALESCE(tp.period_code, gi.return_period, sa.return_period, gb.return_period, '000000') as period, UPPER(COALESCE(pi.source_section, gi.source_section, sa.source_section, gb.source_section, 'OTHER')) as category, "rr"."id" as "result_id", "rr"."match_status", "pi"."book_vchr_no" as "vchr_no", COALESCE(pi.supplier_name, gi.supplier_name, sa.supplier_name, gb.supplier_name, 'Unknown') as supplier_name, COALESCE(pi.supplier_gstin, gi.supplier_gstin, sa.supplier_gstin, gb.supplier_gstin) as supplier_gstin, COALESCE(pi.supplier_invoice_no, gi.document_number_clean, sa.document_number_clean, gb.document_number_clean) as invoice_no, COALESCE(pi.supplier_invoice_date, gi.document_date, sa.document_date, gb.document_date) as invoice_date, (COALESCE(pi.total_igst_amount,0) + COALESCE(pi.total_cgst_amount,0) + COALESCE(pi.total_sgst_amount,0) + COALESCE(pi.total_cess_amount,0) + COALESCE(sa.total_tax, 0)) as books_tax, COALESCE(pi.total_igst_amount, sa.igst, 0) as books_igst, COALESCE(pi.total_cgst_amount, sa.cgst, 0) as books_cgst, COALESCE(pi.total_sgst_amount, sa.sgst, 0) as books_sgst, COALESCE(pi.total_cess_amount, sa.cess, 0) as books_cess, COALESCE(gi.total_tax, gb.total_tax, 0) as gstr_tax, COALESCE(gi.total_tax, 0) as gstr2a_tax, COALESCE(gi.igst, gb.igst, 0) as gstr_igst, COALESCE(gi.cgst, gb.cgst, 0) as gstr_cgst, COALESCE(gi.sgst, gb.sgst, 0) as gstr_sgst, COALESCE(gi.cess, gb.cess, 0) as gstr_cess, COALESCE(gi.igst, 0) as gstr2a_igst, COALESCE(gi.cgst, 0) as gstr2a_cgst, COALESCE(gi.sgst, 0) as gstr2a_sgst, COALESCE(gi.cess, 0) as gstr2a_cess from "reconciliation_results" as "rr" left join "reconciliation_runs" as "r" on "rr"."recon_run_id" = "r"."id" left join "normalized_gstr2a_invoices" as "gi" on "rr"."gstr2a_invoice_id" = "gi"."id" left join "purchase_vouchers" as "pi" on "rr"."purchase_invoice_id" = "pi"."id" left join "normalized_gstr2a_invoices" as "sa" on "rr"."gstr2a_source_id" = "sa"."id" left join "normalized_gstr2b_invoices" as "gb" on "rr"."gstr2b_invoice_id" = "gb"."id" left join "tax_periods" as "tp" on "pi"."tax_period_id" = "tp"."id" where "rr"."workspace_id" = 'b2f6cd54-328c-4dc2-bb45-825548717186' and "r"."run_type" in ('PURCHASE_2A', 'GSTR2A_VS_GSTR2B', 'PURCHASE_2A_VS_2B') limit 2000;
